import { Link } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";

export function Brand() {
  // Generated by `pnpm brand:assets`.
  return (
    <img
      className="brand"
      src="/brand/yarrow-logo-on-dark.svg"
      alt="Yarrow"
      width={107}
      height={24}
    />
  );
}

type HeaderViewer = {
  name: string | null;
  githubLogin: string | null;
  avatarUrl: string | null;
  email?: string | null;
  /** Paid from this browser without an account. */
  guest?: boolean;
} | null;

export function SiteHeader({ viewer }: { viewer: HeaderViewer }) {
  const [open, setOpen] = useState(false);
  const menu = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (event: MouseEvent) => {
      if (!menu.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, [open]);
  const label =
    viewer?.githubLogin ?? viewer?.name ?? viewer?.email ?? "Account";
  return (
    <header className="site-header">
      <div className="container header-inner">
        {/* Balances the account menu so the logo sits in the middle. */}
        <span aria-hidden="true" />
        <Link to="/" aria-label="Yarrow home" className="header-brand">
          <Brand />
        </Link>
        <div className="header-actions" ref={menu}>
          {viewer ? (
            <>
              <button
                className="avatar-button"
                aria-label={`${label} menu`}
                aria-haspopup="menu"
                aria-expanded={open}
                onClick={() => setOpen(!open)}
              >
                {viewer.avatarUrl ? (
                  <img src={viewer.avatarUrl} alt="" />
                ) : (
                  label.charAt(0).toUpperCase()
                )}
              </button>
              {open && (
                <div className="account-menu" role="menu">
                  <Link
                    to="/dashboard"
                    role="menuitem"
                    onClick={() => setOpen(false)}
                  >
                    Dashboard
                  </Link>
                  {viewer.guest && (
                    <a href="/sign-in?next=/dashboard" role="menuitem">
                      Sign in
                    </a>
                  )}
                  <a href="/auth/sign-out" role="menuitem" className="muted">
                    Sign out
                  </a>
                </div>
              )}
            </>
          ) : (
            <Link to="/sign-in" className="sign-in">
              Sign in
            </Link>
          )}
        </div>
      </div>
    </header>
  );
}
